      test('$path exists', () {
        expect(
          File(path).existsSync(),
          isTrue,
          reason: 'README links $path but the file is absent — a dead link '
              'on main and, if it documents a command, a failing command '
              '(gh-137 PR #138 BLOCKING review thread)',
        );
      });
    }
  });
}

