        reason: 'gitlink must be a full SHA');
    final yml = File(_teammateStub).readAsStringSync();
    final match = _agenticUsesRe.firstMatch(yml);
    expect(match, isNotNull,
        reason: '$_teammateStub must call dmtools-agentic-workflows');
    expect(
      match!.group(1),
