      expect(
        yaml.contains(r"dryRun: ${{ github.event.inputs.dryRun || 'false' }}"),
        isTrue,
        reason: 'manual ticks default to dry; cron ticks run live — the '
            'input must fall through exactly that way (STRING: boolean '
